//! The configuration of a Rust-first project (specification 48 RU-66, RU-67, Appendix B):
//! `trust.toml`'s resource, its tasks, its program instances, its globals and its bindings as one
//! Structured Text `CONFIGURATION`, in the order `trust.toml` gives them. Each value is checked
//! before it is written, so the generated file holds no text a `trust.toml` value could break; the
//! check of the whole project then checks the configuration as any (RU-41, step 2).

use std::fmt::Write as _;
use std::path::Path;

use toml_edit::{DocumentMut, Item, TableLike};
use trust_plc_decl::Kind;

use super::RustCrate;

/// The text of the configuration `trust.toml` in `project` declares, whose programs are the Rust
/// programs of `krate`.
///
/// # Errors
///
/// A `trust.toml` that does not read, and each value that breaks Appendix B's schema: a resource
/// without a name, a task without an interval or an event, a program instance of no Rust program
/// of the crate or of no task, a global without a type, a binding of no program variable or to no
/// directly represented variable.
pub(super) fn configuration_text(project: &Path, krate: &RustCrate) -> Result<String, String> {
    let text =
        std::fs::read_to_string(project.join("trust.toml")).map_err(|error| error.to_string())?;
    let document = text
        .parse::<DocumentMut>()
        .map_err(|error| error.to_string())?;
    let resource = document
        .get("resource")
        .and_then(Item::as_table_like)
        .and_then(|resource| resource.get("name"))
        .and_then(Item::as_str)
        .filter(|name| is_name(name))
        .ok_or("[resource] name is the resource's name, an identifier")?;
    let mut out = String::from("(* GENERATED by trust-runtime from trust.toml - do not edit *)\n");
    let _ = writeln!(out, "CONFIGURATION {resource}");
    globals(&mut out, table(&document, "globals"))?;
    let _ = writeln!(out, "RESOURCE {resource} ON PLC");
    let tasks = tasks(&mut out, table(&document, "tasks"))?;
    let programs = programs(&mut out, table(&document, "programs"), &tasks, krate)?;
    out.push_str("END_RESOURCE\n");
    bindings(&mut out, table(&document, "bindings"), &programs, krate)?;
    out.push_str("END_CONFIGURATION\n");
    Ok(out)
}

/// The table `key` of `document`, `None` without one.
fn table<'d>(document: &'d DocumentMut, key: &str) -> Option<&'d dyn TableLike> {
    document.get(key).and_then(Item::as_table_like)
}

/// `[globals]`: each `Name = { type = "...", init = "..." }` as a `VAR_GLOBAL` variable.
fn globals(out: &mut String, globals: Option<&dyn TableLike>) -> Result<(), String> {
    let Some(globals) = globals.filter(|globals| !globals.is_empty()) else {
        return Ok(());
    };
    out.push_str("VAR_GLOBAL\n");
    for (name, global) in globals.iter() {
        if !is_name(name) {
            return Err(format!("[globals] {name} is no identifier"));
        }
        let global = global.as_table_like();
        let ty = global
            .and_then(|global| global.get("type"))
            .and_then(Item::as_str)
            .filter(|ty| is_text(ty))
            .ok_or_else(|| format!("[globals] {name} has its type: {{ type = \"REAL\" }}"))?;
        let _ = write!(out, "    {name} : {ty}");
        if let Some(init) = global.and_then(|global| global.get("init")) {
            let init = init
                .as_str()
                .filter(|init| is_text(init))
                .ok_or_else(|| format!("[globals] {name} init is its value as text: \"1.5\""))?;
            let _ = write!(out, " := {init}");
        }
        out.push_str(";\n");
    }
    out.push_str("END_VAR\n");
    Ok(())
}

/// `[tasks.<name>]`: each a `TASK` with its `interval` or its `event`, and its `priority`. Gives
/// the tasks' names.
fn tasks(out: &mut String, tasks: Option<&dyn TableLike>) -> Result<Vec<String>, String> {
    let mut names = Vec::new();
    for (name, task) in tasks.into_iter().flat_map(TableLike::iter) {
        if !is_name(name) {
            return Err(format!("[tasks.{name}] is no identifier"));
        }
        let task = task
            .as_table_like()
            .ok_or_else(|| format!("[tasks.{name}] is a table"))?;
        let start = match (
            task.get("interval").and_then(Item::as_str),
            task.get("event").and_then(Item::as_str),
        ) {
            (Some(interval), None) => match trust_plc_decl::duration_nanoseconds(interval) {
                Some(nanos) => format!("INTERVAL := {}", time_literal(nanos)),
                None => {
                    return Err(format!(
                        "[tasks.{name}] interval \"{interval}\" is no duration: \
                         `10ms`, `500us`, `1s`"
                    ))
                }
            },
            (None, Some(event)) if is_name(event) => format!("SINGLE := {event}"),
            _ => {
                return Err(format!(
                    "[tasks.{name}] runs at an interval, `interval = \"10ms\"`, or \
                     at an event, `event = \"Trigger\"`, a BOOL global (specification 48 RU-66)"
                ))
            }
        };
        let priority = task
            .get("priority")
            .and_then(Item::as_integer)
            .filter(|priority| *priority >= 0)
            .ok_or_else(|| format!("[tasks.{name}] has its priority: `priority = 1`"))?;
        let _ = writeln!(out, "    TASK {name} ({start}, PRIORITY := {priority});");
        names.push(name.to_string());
    }
    Ok(names)
}

/// `[programs.<name>]`: each instance of a Rust program of `krate` on one of `tasks`. Gives each
/// instance's name with its program's.
fn programs(
    out: &mut String,
    programs: Option<&dyn TableLike>,
    tasks: &[String],
    krate: &RustCrate,
) -> Result<Vec<(String, String)>, String> {
    let mut instances = Vec::new();
    for (name, program) in programs.into_iter().flat_map(TableLike::iter) {
        if !is_name(name) {
            return Err(format!("[programs.{name}] is no identifier"));
        }
        let program = program.as_table_like();
        let ty = program
            .and_then(|program| program.get("type"))
            .and_then(Item::as_str)
            .unwrap_or_default();
        let Some(declared) = krate
            .pous
            .iter()
            .find(|pou| pou.pou.kind == Kind::Program && pou.pou.name.eq_ignore_ascii_case(ty))
        else {
            return Err(format!(
                "[programs.{name}] type \"{ty}\" names no `#[trust_program]` of the \
                 crate (specification 48 RU-35, RU-66)"
            ));
        };
        let task = program
            .and_then(|program| program.get("task"))
            .and_then(Item::as_str)
            .unwrap_or_default();
        if !tasks.iter().any(|known| known.eq_ignore_ascii_case(task)) {
            return Err(format!(
                "[programs.{name}] task \"{task}\" names no task of [tasks]"
            ));
        }
        let _ = writeln!(
            out,
            "    PROGRAM {name} WITH {task} : {};",
            declared.pou.name
        );
        instances.push((name.to_string(), declared.pou.name.clone()));
    }
    Ok(instances)
}

/// `[bindings]`: each `"Instance.variable" = "%IX0.0"` as a `VAR_CONFIG` entry with the variable's
/// type, its Rust program's declaration's (IEC §6.8.2, Table 62).
fn bindings(
    out: &mut String,
    bindings: Option<&dyn TableLike>,
    instances: &[(String, String)],
    krate: &RustCrate,
) -> Result<(), String> {
    let Some(bindings) = bindings.filter(|bindings| !bindings.is_empty()) else {
        return Ok(());
    };
    out.push_str("VAR_CONFIG\n");
    for (path, address) in bindings.iter() {
        let address = address
            .as_str()
            .filter(|address| is_address(address))
            .ok_or_else(|| {
                format!(
                    "[bindings] \"{path}\" binds a directly represented variable: \
                     \"%IX0.0\""
                )
            })?;
        let (instance, variable) = path.split_once('.').unwrap_or((path, ""));
        let program = instances
            .iter()
            .find(|(name, _)| name.eq_ignore_ascii_case(instance))
            .and_then(|(_, program)| {
                krate
                    .pous
                    .iter()
                    .find(|pou| pou.pou.name.eq_ignore_ascii_case(program))
            });
        let Some(declared) = program.and_then(|pou| {
            pou.pou
                .variables
                .iter()
                .find(|declared| declared.name.eq_ignore_ascii_case(variable))
        }) else {
            return Err(format!(
                "[bindings] \"{path}\" names no variable of a program instance of \
                 [programs]"
            ));
        };
        let _ = writeln!(
            out,
            "    {instance}.{} AT {address} : {};",
            declared.name,
            declared.ty.iec()
        );
    }
    out.push_str("END_VAR\n");
    Ok(())
}

/// The `TIME` literal of `nanos` in the largest unit that holds it whole (IEC §6.3.6, Table 8):
/// `T#10ms`, `T#500us`, `T#1s`.
fn time_literal(nanos: u64) -> String {
    match nanos {
        nanos if nanos % 1_000_000_000 == 0 => format!("T#{}s", nanos / 1_000_000_000),
        nanos if nanos % 1_000_000 == 0 => format!("T#{}ms", nanos / 1_000_000),
        nanos if nanos % 1_000 == 0 => format!("T#{}us", nanos / 1_000),
        nanos => format!("T#{nanos}ns"),
    }
}

/// Whether `name` is an identifier (IEC §6.1.2): a letter or `_`, then letters, digits and `_`.
pub(super) fn is_name(name: &str) -> bool {
    let mut chars = name.chars();
    chars
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        && chars.all(|char| char.is_ascii_alphanumeric() || char == '_')
}

/// Whether `text`, a type or an initial value, stays within one declaration: no line end, no `;`
/// and no comment.
fn is_text(text: &str) -> bool {
    !text.trim().is_empty()
        && !text.contains(['\n', '\r', ';'])
        && !text.contains("(*")
        && !text.contains("*)")
        && !text.contains("//")
}

/// Whether `address` is a directly represented variable (IEC §6.5.5, Table 16): `%`, `I`, `Q` or
/// `M`, a size `X`, `B`, `W`, `D` or `L` or none, and its numbers separated by `.`.
fn is_address(address: &str) -> bool {
    let Some(rest) = address.strip_prefix('%') else {
        return false;
    };
    let mut chars = rest.chars();
    if !chars
        .next()
        .is_some_and(|area| matches!(area, 'I' | 'Q' | 'M'))
    {
        return false;
    }
    let rest: String = chars.collect();
    let numbers = rest
        .strip_prefix(['X', 'B', 'W', 'D', 'L'])
        .unwrap_or(&rest);
    !numbers.is_empty()
        && numbers
            .split('.')
            .all(|part| !part.is_empty() && part.chars().all(|char| char.is_ascii_digit()))
}

